css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .5); height: var(--loader-size); position: relative; display: flex; flex-direction: column; align-items: center; padding-top: 8%; }
.loader::before { content: ''; position: absolute; top: 0; left: 40%; width: 20%; height: 9%; border: calc(var(--loader-size) * .028) solid #94a3b8; border-top: 0; border-radius: 0 0 999px 999px; }
.loader span { width: 52%; height: 30%; border: calc(var(--loader-size) * .045) solid var(--accent); border-radius: 999px; transform-origin: top center; animation: dangle calc(var(--loader-speed) * 1.9) ease-in-out infinite; }
.loader span:nth-child(2) { margin-top: -9%; border-color: var(--accent-2); animation-delay: calc(var(--loader-speed) * .14); }
.loader span:nth-child(3) { margin-top: -9%; animation-delay: calc(var(--loader-speed) * .28); }
@keyframes dangle { 0%, 100% { transform: rotate(-12deg); } 50% { transform: rotate(12deg); } }
